1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	}
56	
57	func newMetricStore() *metricStore {
58		return &metricStore{series: make(map[string]*series)}
59	}
60	
61	// validatedSample is a sample that passed all format and value checks.
62	type validatedSample struct {
63		key     string
64		name    string
65		typ     string
66		labels  map[string]string
67		value   float64
68		buckets []float64 // non-nil for histograms
69	}
70	
71	// checkAndApply validates the batch against the current state (and against
72	// itself) and then commits it in array order. A false result signals a type or
73	// bucket-boundary conflict; in that case no state is mutated.
74	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
75		s.mu.Lock()
76		defer s.mu.Unlock()
77	
78		// First pass: conflict detection against committed state and earlier
79		// samples in the same batch.
80		resolved := make(map[string]*series, len(batch))
81		for _, sm := range batch {
82			existing, ok := s.series[sm.key]
83			if !ok {
84				if shadow, seen := resolved[sm.key]; seen {
85					existing, ok = shadow, true
86				}
87			}
88			if ok {
89				if existing.typ != sm.typ {
90					return false
91				}
92				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
93					return false
94				}
95				resolved[sm.key] = existing
96				continue
97			}
98			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
99		}
100	
101		// Second pass: commit in order.
102		for _, sm := range batch {
103			cur, ok := s.series[sm.key]
104			if !ok {
105				cur = &series{
106					name:         sm.name,
107					typ:          sm.typ,
108					labels:       sm.labels,
109					bucketBounds: append([]float64(nil), sm.buckets...),
110				}
111				if sm.typ == "histogram" {
112					cur.bucketCounts = make([]int64, len(sm.buckets))
113				}
114				s.series[sm.key] = cur
115			}
116			switch sm.typ {
117			case "counter":
118				cur.value += sm.value
119			case "gauge":
120				cur.value = sm.value
121			case "histogram":
122				cur.count++
123				cur.sum += sm.value
124				for i, bound := range cur.bucketBounds {
125					if sm.value <= bound {
126						cur.bucketCounts[i]++
127					}
128				}
129			}
130		}
131		return true
132	}
133	
134	type seriesOutput struct {
135		Name    string            `json:"name"`
136		Type    string            `json:"type"`
137		Labels  map[string]string `json:"labels"`
138		Value   *float64          `json:"value,omitempty"`
139		Count   *int64            `json:"count,omitempty"`
140		Sum     *float64          `json:"sum,omitempty"`
141		Buckets []bucketOutput    `json:"buckets,omitempty"`
142	}
143	
144	type bucketOutput struct {
145		LE    float64 `json:"le"`
146		Count int64   `json:"count"`
147	}
148	
149	// query returns matching series as ready-to-encode outputs. A series matches
150	// when its name equals name exactly and it contains every selector label.
151	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
152		s.mu.RLock()
153		defer s.mu.RUnlock()
154	
155		out := make([]seriesOutput, 0)
156		for _, cur := range s.series {
157			if cur.name != name {
158				continue
159			}
160			matched := true
161			for k, v := range selector {
162				got, ok := cur.labels[k]
163				if !ok || got != v {
164					matched = false
165					break
166				}
167			}
168			if !matched {
169				continue
170			}
171			item := seriesOutput{
172				Name:   cur.name,
173				Type:   cur.typ,
174				Labels: copyLabels(cur.labels),
175			}
176			switch cur.typ {
177			case "counter", "gauge":
178				v := cur.value
179				item.Value = &v
180			case "histogram":
181				c, sum := cur.count, cur.sum
182				item.Count = &c
183				item.Sum = &sum
184				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
185				for i, bound := range cur.bucketBounds {
186					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
187				}
188			}
189			out = append(out, item)
190		}
191	
192		sort.Slice(out, func(i, j int) bool {
193			return compareLabels(out[i].Labels, out[j].Labels) < 0
194		})
195		return out
196	}
197	
198	// compareLabels imposes a normalized lexicographic order on full label sets:
199	// keys are sorted, then (key, value) pairs are compared element-wise, and a
200	// shorter pair list sorts first when it is a prefix of a longer one.
201	func compareLabels(a, b map[string]string) int {
202		ka := sortedKeys(a)
203		kb := sortedKeys(b)
204		n := len(ka)
205		if len(kb) < n {
206			n = len(kb)
207		}
208		for i := 0; i < n; i++ {
209			if ka[i] != kb[i] {
210				return strings.Compare(ka[i], kb[i])
211			}
212			if a[ka[i]] != b[kb[i]] {
213				return strings.Compare(a[ka[i]], b[kb[i]])
214			}
215		}
216		switch {
217		case len(ka) < len(kb):
218			return -1
219		case len(ka) > len(kb):
220			return 1
221		default:
222			return 0
223		}
224	}
225	
226	func sortedKeys(m map[string]string) []string {
227		keys := make([]string, 0, len(m))
228		for k := range m {
229			keys = append(keys, k)
230		}
231		sort.Strings(keys)
232		return keys
233	}
234	
235	func copyLabels(in map[string]string) map[string]string {
236		out := make(map[string]string, len(in))
237		for k, v := range in {
238			out[k] = v
239		}
240		return out
241	}
242	
243	// seriesKey builds a collision-free identity from name + unordered labels.
244	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
245	// so length-prefixed values remove any ambiguity from arbitrary label values.
246	func seriesKey(name string, labels map[string]string) string {
247		var b strings.Builder
248		b.WriteString(name)
249		for _, k := range sortedKeys(labels) {
250			b.WriteByte(0)
251			b.WriteString(k)
252			b.WriteByte(0)
253			v := labels[k]
254			b.WriteString(strconv.Itoa(len(v)))
255			b.WriteByte(0)
256			b.WriteString(v)
257		}
258		return b.String()
259	}
260	
261	func equalBuckets(a, b []float64) bool {
262		if len(a) != len(b) {
263			return false
264		}
265		for i := range a {
266			if a[i] != b[i] {
267				return false
268			}
269		}
270		return true
271	}
272	
273	// Handler returns the HTTP surface served by SignalWatch.
274	func Handler() http.Handler {
275		mux := http.NewServeMux()
276		store := newMetricStore()
277	
278		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
279			if r.Method != http.MethodGet {
280				w.Header().Set("Allow", http.MethodGet)
281				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
282				return
283			}
284			w.Header().Set("Content-Type", "application/json; charset=utf-8")
285			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
286		})
287	
288		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
289			switch r.Method {
290			case http.MethodGet:
291				handleMetricsGet(w, r, store)
292			case http.MethodPost:
293				handleMetricsPost(w, r, store)
294			default:
295				w.Header().Set("Allow", "GET, POST")
296				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
297			}
298		})
299	
300		return mux
301	}
302	
303	func handleMetricsPost(w http.ResponseWriter, r *http.Request, store *metricStore) {
304		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
305		if err != nil || mediaType != "application/json" {
306			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
307			return
308		}
309	
310		body, err := io.ReadAll(r.Body)
311		if err != nil {
312			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
313			return
314		}
315	
316		batch, ok := decodeMetricsBatch(body)
317		if !ok {
318			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
319			return
320		}
321	
322		if !store.checkAndApply(batch) {
323			writeAPIError(w, "metric_conflict", http.StatusConflict)
324			return
325		}
326	
327		w.Header().Set("Content-Type", "application/json; charset=utf-8")
328		w.WriteHeader(http.StatusAccepted)
329		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
330	}
331	
332	type metricsEnvelope struct {
333		Samples *[]json.RawMessage `json:"samples"`
334	}
335	
336	type rawSample struct {
337		Name    *string            `json:"name"`
338		Type    *string            `json:"type"`
339		Labels  *map[string]string `json:"labels"`
340		Value   *float64           `json:"value"`
341		Buckets *[]float64         `json:"buckets"`
342	}
343	
344	// decodeMetricsBatch performs every format and value check. It never returns a
345	// partially validated batch.
346	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
347		var env metricsEnvelope
348		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
349			return nil, false
350		}
351	
352		batch := make([]validatedSample, 0, len(*env.Samples))
353		for _, raw := range *env.Samples {
354			var sm rawSample
355			if !strictDecode(raw, &sm) {
356				return nil, false
357			}
358			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
359				return nil, false
360			}
361			name, typ := *sm.Name, *sm.Type
362			if !identPattern.MatchString(name) {
363				return nil, false
364			}
365			if typ != "counter" && typ != "gauge" && typ != "histogram" {
366				return nil, false
367			}
368			labels := *sm.Labels
369			if labels == nil {
370				return nil, false // explicit null labels
371			}
372			for k := range labels {
373				if !identPattern.MatchString(k) {
374					return nil, false
375				}
376			}
377			value := *sm.Value
378			if math.IsNaN(value) || math.IsInf(value, 0) {
379				return nil, false // encoding/json already rejects NaN/Inf tokens
380			}
381			if typ == "counter" && value < 0 {
382				return nil, false
383			}
384	
385			var buckets []float64
386			if typ == "histogram" {
387				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
388					return nil, false
389				}
390				buckets = append([]float64(nil), (*sm.Buckets)...)
391			} else if sm.Buckets != nil {
392				return nil, false // buckets only valid on histograms
393			}
394	
395			batch = append(batch, validatedSample{
396				key:     seriesKey(name, labels),
397				name:    name,
398				typ:     typ,
399				labels:  copyLabels(labels),
400				value:   value,
401				buckets: buckets,
402			})
403		}
404		return batch, true
405	}
406	
407	func validBuckets(buckets []float64) bool {
408		if len(buckets) == 0 {
409			return false
410		}
411		prev := math.Inf(-1)
412		for _, b := range buckets {
413			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
414				return false
415			}
416			prev = b
417		}
418		return true
419	}
420	
421	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
422	// values and non-object payloads for struct targets.
423	func strictDecode(data []byte, target any) bool {
424		dec := json.NewDecoder(bytes.NewReader(data))
425		dec.DisallowUnknownFields()
426		if err := dec.Decode(target); err != nil {
427			return false
428		}
429		var extra json.RawMessage
430		if err := dec.Decode(&extra); err != io.EOF {
431			return false
432		}
433		return true
434	}
435	
436	func handleMetricsGet(w http.ResponseWriter, r *http.Request, store *metricStore) {
437		values, err := url.ParseQuery(r.URL.RawQuery)
438		if err != nil {
439			writeAPIError(w, "invalid_query", http.StatusBadRequest)
440			return
441		}
442	
443		names := values["name"]
444		if len(names) == 0 || !identPattern.MatchString(names[0]) {
445			writeAPIError(w, "invalid_query", http.StatusBadRequest)
446			return
447		}
448	
449		selector := make(map[string]string)
450		for key, vals := range values {
451			if !strings.HasPrefix(key, "label.") {
452				continue
453			}
454			labelKey := strings.TrimPrefix(key, "label.")
455			if !identPattern.MatchString(labelKey) {
456				writeAPIError(w, "invalid_query", http.StatusBadRequest)
457				return
458			}
459			for _, v := range vals[1:] {
460				if v != vals[0] {
461					writeAPIError(w, "invalid_query", http.StatusBadRequest)
462					return
463				}
464			}
465			selector[labelKey] = vals[0]
466		}
467	
468		seriesList := store.query(names[0], selector)
469		w.Header().Set("Content-Type", "application/json; charset=utf-8")
470		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
471	}
472	
473	func writeAPIError(w http.ResponseWriter, code string, status int) {
474		w.Header().Set("Content-Type", "application/json; charset=utf-8")
475		w.WriteHeader(status)
476		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
477	}
478

