1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"math"
7		"mime"
8		"net/http"
9		"sort"
10		"strings"
11	)
12	
13	const (
14		alertRulesPath   = "/api/v1/alert-rules"
15		alertRulesPrefix = alertRulesPath + "/"
16		alertsPath       = "/api/v1/alerts"
17	)
18	
19	// ruleSelector selects series by exact metric name and a subset of labels.
20	type ruleSelector struct {
21		metric string
22		labels map[string]string
23	}
24	
25	// alertRule is an immutable rule document. Replacements swap the pointer
26	// atomically, so readers never observe a half-updated rule.
27	type alertRule struct {
28		id        string
29		kind      string // "threshold" | "ratio"
30		operator  string // gt | gte | lt | lte
31		threshold float64
32	
33		// threshold rules use left only; ratio rules use both sides.
34		left  *ruleSelector
35		right *ruleSelector
36	}
37	
38	// ---- JSON wire shapes ------------------------------------------------------
39	
40	type ruleSideJSON struct {
41		Metric string            `json:"metric"`
42		Labels map[string]string `json:"labels"`
43	}
44	
45	type thresholdRuleJSON struct {
46		ID        string            `json:"id"`
47		Kind      string            `json:"kind"`
48		Operator  string            `json:"operator"`
49		Threshold float64           `json:"threshold"`
50		Metric    string            `json:"metric"`
51		Labels    map[string]string `json:"labels"`
52	}
53	
54	type ratioRuleJSON struct {
55		ID          string       `json:"id"`
56		Kind        string       `json:"kind"`
57		Operator    string       `json:"operator"`
58		Threshold   float64      `json:"threshold"`
59		Numerator   ruleSideJSON `json:"numerator"`
60		Denominator ruleSideJSON `json:"denominator"`
61	}
62	
63	func ruleWireJSON(r *alertRule) any {
64		if r.kind == "ratio" {
65			return ratioRuleJSON{
66				ID:          r.id,
67				Kind:        r.kind,
68				Operator:    r.operator,
69				Threshold:   r.threshold,
70				Numerator:   sideWireJSON(r.left),
71				Denominator: sideWireJSON(r.right),
72			}
73		}
74		return thresholdRuleJSON{
75			ID:        r.id,
76			Kind:      r.kind,
77			Operator:  r.operator,
78			Threshold: r.threshold,
79			Metric:    r.left.metric,
80			Labels:    copyLabels(r.left.labels),
81		}
82	}
83	
84	func sideWireJSON(s *ruleSelector) ruleSideJSON {
85		return ruleSideJSON{Metric: s.metric, Labels: copyLabels(s.labels)}
86	}
87	
88	// ---- request decoding ------------------------------------------------------
89	
90	type rawRuleSide struct {
91		Metric *string            `json:"metric"`
92		Labels *map[string]string `json:"labels"`
93	}
94	
95	type rawRule struct {
96		Kind        *string            `json:"kind"`
97		Operator    *string            `json:"operator"`
98		Threshold   *float64           `json:"threshold"`
99		Metric      *string            `json:"metric"`
100		Labels      *map[string]string `json:"labels"`
101		Numerator   *rawRuleSide       `json:"numerator"`
102		Denominator *rawRuleSide       `json:"denominator"`
103	}
104	
105	// decodeRule parses and fully validates a rule body. It never returns a
106	// partially validated rule.
107	func decodeRule(body []byte) (*alertRule, bool) {
108		var raw rawRule
109		if !strictDecode(body, &raw) {
110			return nil, false
111		}
112		if raw.Kind == nil || raw.Operator == nil || raw.Threshold == nil {
113			return nil, false
114		}
115		kind := *raw.Kind
116		if kind != "threshold" && kind != "ratio" {
117			return nil, false
118		}
119		operator := *raw.Operator
120		if !validOperators[operator] {
121			return nil, false
122		}
123		threshold := *raw.Threshold
124		if math.IsNaN(threshold) || math.IsInf(threshold, 0) {
125			return nil, false
126		}
127	
128		build := func() *alertRule {
129			return &alertRule{kind: kind, operator: operator, threshold: threshold}
130		}
131	
132		switch kind {
133		case "threshold":
134			if raw.Metric == nil || raw.Labels == nil || raw.Numerator != nil || raw.Denominator != nil {
135				return nil, false
136			}
137			sel, ok := decodeSelector(*raw.Metric, *raw.Labels)
138			if !ok {
139				return nil, false
140			}
141			r := build()
142			r.left = sel
143			return r, true
144		case "ratio":
145			if raw.Metric != nil || raw.Labels != nil || raw.Numerator == nil || raw.Denominator == nil {
146				return nil, false
147			}
148			num, ok := decodeRawSide(raw.Numerator)
149			if !ok {
150				return nil, false
151			}
152			den, ok := decodeRawSide(raw.Denominator)
153			if !ok {
154				return nil, false
155			}
156			r := build()
157			r.left, r.right = num, den
158			return r, true
159		}
160		return nil, false
161	}
162	
163	func decodeRawSide(raw *rawRuleSide) (*ruleSelector, bool) {
164		if raw.Metric == nil || raw.Labels == nil {
165			return nil, false
166		}
167		return decodeSelector(*raw.Metric, *raw.Labels)
168	}
169	
170	func decodeSelector(metric string, labels map[string]string) (*ruleSelector, bool) {
171		if !identPattern.MatchString(metric) || labels == nil {
172			return nil, false
173		}
174		for k := range labels {
175			if !identPattern.MatchString(k) {
176				return nil, false
177			}
178		}
179		return &ruleSelector{metric: metric, labels: copyLabels(labels)}, true
180	}
181	
182	var validOperators = map[string]bool{
183		"gt":  true,
184		"gte": true,
185		"lt":  true,
186		"lte": true,
187	}
188	
189	// ---- store operations ------------------------------------------------------
190	
191	func (s *metricStore) putRule(r *alertRule) bool {
192		s.mu.Lock()
193		defer s.mu.Unlock()
194		_, existed := s.rules[r.id]
195		s.rules[r.id] = r
196		return !existed
197	}
198	
199	func (s *metricStore) getRule(id string) (*alertRule, bool) {
200		s.mu.RLock()
201		defer s.mu.RUnlock()
202		r, ok := s.rules[id]
203		return r, ok
204	}
205	
206	func (s *metricStore) deleteRule(id string) bool {
207		s.mu.Lock()
208		defer s.mu.Unlock()
209		if _, ok := s.rules[id]; !ok {
210			return false
211		}
212		delete(s.rules, id)
213		return true
214	}
215	
216	// snapshotRules returns all rules sorted by id. Rule objects are immutable,
217	// so the pointers stay safe after the lock is released.
218	func (s *metricStore) snapshotRules() []*alertRule {
219		s.mu.RLock()
220		defer s.mu.RUnlock()
221		out := make([]*alertRule, 0, len(s.rules))
222		for _, r := range s.rules {
223			out = append(out, r)
224		}
225		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
226		return out
227	}
228	
229	// selectorSum sums current values of all matching counter/gauge series.
230	// ok is false when no counter/gauge series matches; histograms are ignored,
231	// so a selector matching histograms only counts as unavailable.
232	func (s *metricStore) selectorSum(sel *ruleSelector) (sum float64, ok bool) {
233		for _, cur := range s.series {
234			if cur.typ != "counter" && cur.typ != "gauge" {
235				continue
236			}
237			if cur.name != sel.metric {
238				continue
239			}
240			matched := true
241			for k, v := range sel.labels {
242				got, exists := cur.labels[k]
243				if !exists || got != v {
244					matched = false
245					break
246				}
247			}
248			if !matched {
249				continue
250			}
251			sum += cur.value
252			ok = true
253		}
254		return sum, ok
255	}
256	
257	type alertOutput struct {
258		ID    string   `json:"id"`
259		State string   `json:"state"`
260		Value *float64 `json:"value"`
261	}
262	
263	// evalAlerts computes every rule against a single consistent snapshot of
264	// metrics and rules; results are sorted by rule id.
265	func (s *metricStore) evalAlerts() []alertOutput {
266		s.mu.RLock()
267		defer s.mu.RUnlock()
268	
269		rules := make([]*alertRule, 0, len(s.rules))
270		for _, r := range s.rules {
271			rules = append(rules, r)
272		}
273		sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })
274	
275		out := make([]alertOutput, 0, len(rules))
276		for _, r := range rules {
277			al := alertOutput{ID: r.id, State: "inactive"}
278	
279			var value float64
280			if r.kind == "threshold" {
281				sum, ok := s.selectorSum(r.left)
282				if !ok {
283					al.State = "no_data"
284					out = append(out, al)
285					continue
286				}
287				value = sum
288			} else {
289				num, numOK := s.selectorSum(r.left)
290				den, denOK := s.selectorSum(r.right)
291				if !numOK || !denOK || den == 0 {
292					al.State = "no_data"
293					out = append(out, al)
294					continue
295				}
296				value = num / den
297			}
298	
299			v := value
300			al.Value = &v
301			if compareHolds(r.operator, value, r.threshold) {
302				al.State = "firing"
303			}
304			out = append(out, al)
305		}
306		return out
307	}
308	
309	func compareHolds(operator string, value, threshold float64) bool {
310		switch operator {
311		case "gt":
312			return value > threshold
313		case "gte":
314			return value >= threshold
315		case "lt":
316			return value < threshold
317		case "lte":
318			return value <= threshold
319		}
320		return false
321	}
322	
